    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('Jadwal Pelayanan') || ss.insertSheet('Jadwal Pelayanan');
    sheet.clearContents(); sheet.clearFormats(); sheet.setFrozenRows(0);
